export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/about/" : "/en/about/";
  const alternates = [
    { hrefLang: "fr", href: "https://riano.ca/fr/about/" },
    { hrefLang: "en", href: "https://riano.ca/en/about/" },
    { hrefLang: "x-default", href: "https://riano.ca/fr/about/" },
  ];

  return (
    <SEO
      data={info}
      titleKey="seo.about.metaTitle"
      descriptionKey="seo.about.metaDescription"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={alternates}
      schemaType="ProfessionalService"
    />
  );
};
